    31	/** One player of the room, as the room shows them. */
    32	export interface RoomPlayer {
    33	  name: string;
    34	  avatar: Avatar | null;
    35	  /** True for the player at this device. */
    36	  you: boolean;
    37	  /** True to tag them as "You" - not when "You" is their name already. */
    38	  youTag: boolean;
    39	  /** Their colony's colour, as a CSS colour. */
    40	  color: string;
    41	  /** True for the winner of the match just played. */
    42	  won: boolean;
    43	}
    44	
    45	/**
    46	 * The room two connected players share, before the first match and between
    47	 * matches: both players face to face with the room's tally, and the next
    48	 * match's level. The host picks it here - every pick reaches the guest
    49	 * through the setup the host already shares - and the guest watches it
    50	 * change. Starting stays with the screen around it.
    51	 */
    52	@Component({
    53	  selector: 'feat-lazy-bac-game-online-room',
    54	  imports: [
    55	    AvatarComponent,
    56	    LevelCardComponent,
    57	    LevelPreviewComponent,
    58	    MatIconModule,
    59	    TranslatePipe,
    60	  ],
    61	  templateUrl: './online-room.component.html',
    62	  styleUrl: './online-room.component.scss',
    63	  changeDetection: ChangeDetectionStrategy.OnPush,
    64	})
    65	export class OnlineRoomComponent {
    66	  private readonly store = inject(GameStateStore);
    67	  private readonly gameState = inject(GameStateService);
    68	  private readonly social = inject(SocialService);
    69	  private readonly i18n = inject(I18nService);
    70	  protected readonly previews = inject(LevelPreviewService).supported;
    71	  protected readonly tally = inject(RoomTally).tally;
    72	
    73	  /** The seat of the match just won, on a result - null before one. */
    74	  public readonly winner = input<0 | 1 | null>(null);
    75	
    76	  /** This device's online seat - null without a connection. */
    77	  protected readonly seat = this.store.online;
    78	
    79	  /** The host (left) and the guest (right). */
    80	  protected readonly players = computed((): RoomPlayer[] => {
    81	    const seat = this.seat();
    82	    if (seat === null) {
    83	      return [];
    84	    }
    85	    const own = this.social.profile();
    86	    const opponent = this.social.opponent()?.card ?? null;
    87	    const me = {
    88	      name: own?.name ?? this.i18n.t('online.room.you'),
    89	      avatar: own?.avatar ?? null,
    90	    };
    91	    const them = {
    92	      name: opponent?.name ?? this.i18n.t('online.room.opponent'),
    93	      avatar: opponent?.avatar ?? null,
    94	    };
    95	    return ([0, 1] as const).map((index) => {
    96	      const you = index === seat.seat;
    97	      return {
    98	        ...(you ? me : them),
    99	        you,
   100	        youTag: you && own !== null,
   101	        color: cssColor(seat.colors[index]),
   102	        won: this.winner() === index,
   103	      };
   104	    });
   105	  });
   106	
   107	  /** The level of the next match. */
   108	  protected readonly next = computed(() => {
   109	    const levelId = this.seat()?.levelId;
   110	    return levelId === undefined ? null : this.card(levelId);
   111	  });
   112	
   113	  /** The levels the host may pick from. */
   114	  protected readonly cards = computed(() =>
   115	    MATCH_LEVELS.map((level) => this.card(level.id))
   116	  );
   117	
   118	  /** What the guest reads while the host picks. */
   119	  protected readonly choosing = computed(() => {
   120	    const name = this.social.opponent()?.card.name;
   121	    return name === undefined
   122	      ? this.i18n.t('online.room.choosingAnon')
   123	      : this.i18n.t('online.room.choosing', { name });
   124	  });
   125	
   126	  protected pick(levelId: string): void {
   127	    if (this.seat()?.seat === 0) {
   128	      this.gameState.setLevel(levelId);
   129	    }
   130	  }
   131	
   132	  /**
   133	   * A level's card: its place on the ladder, its title in the active
   134	   * language and its arena's colours. Online there are no medallions and
   135	   * no locks.
   136	   */
   137	  private card(id: string): LevelCard {
   138	    const level = getLevel(id);
   139	    return {
   140	      id: level.id,
   141	      badge: String(LEVELS.indexOf(level) + 1),
   142	      title: this.text(levelTitleText(level)),
   143	      lock: null,
   144	      ...levelColors(level.id),
   145	      size: levelSize(level),
   146	      medals: [],
   147	    };
   148	  }
   149	
   150	  private text(text: GameText): string {
   151	    return renderGameText(text, (key, params) => this.i18n.t(key, params));
   152	  }
   153	}
   154	
   155	function cssColor(colorId: string): string {
   156	  const [r, g, b] = getColonyColor(colorId).rgb;
   157	  return `rgb(${r} ${g} ${b})`;
   158	}
