     5	/** The wins of an online room: the host's (left) first, the guest's second. */
     6	export type Tally = readonly [host: number, guest: number];
     7	
     8	export const EMPTY_TALLY: Tally = [0, 0];
     9	
    10	/** The tally after a match `winner` won - a draw (null) counts for nobody. */
    11	export function countResult(tally: Tally, winner: 0 | 1 | null): Tally {
    12	  if (winner === null) {
    13	    return tally;
    14	  }
    15	  return winner === 0 ? [tally[0] + 1, tally[1]] : [tally[0], tally[1] + 1];
    16	}
    17	
    18	/**
    19	 * Counts the wins of the matches two devices played over one connection,
    20	 * for the room both players see. A new connection starts at nought; the
    21	 * end of one keeps its count, so its last result still shows it.
    22	 */
    23	@Injectable({ providedIn: 'root' })
    24	export class RoomTally {
    25	  private readonly state = signal<Tally>(EMPTY_TALLY);
    26	
    27	  public readonly tally = this.state.asReadonly();
    28	
    29	  public constructor() {
    30	    inject(OnlineMatchService)
    31	      .events$.pipe(filter((event) => event.type === 'connected'))
    32	      .subscribe(() => this.state.set(EMPTY_TALLY));
    33	  }
    34	
    35	  /** Counts a match of the room for the seat that won it. */
    36	  public count(winner: 0 | 1 | null): void {
    37	    this.state.update((tally) => countResult(tally, winner));
    38	  }
    39	}
